begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','agency@example.invalid',now()),('33333333-3333-4333-8333-333333333333','staff@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Delegation brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('invite',public.create_brand_invitation((select id from fixture where key='brand'),'agency@example.invalid','operator',gen_random_uuid()));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
insert into fixture values('agency',public.create_agency('Agency',gen_random_uuid()));
select public.accept_brand_invitation((select id from fixture where key='invite'),(select id from fixture where key='agency'));
insert into fixture select 'grant',id from public.brand_access_grants;
select ok(not public.current_brand_capability((select id from fixture where key='brand'),'knowledge.write'),'Connection role does not imply fact editing');
select throws_ok($$select public.set_agency_capabilities((select id from fixture where key='brand'),(select id from fixture where key='grant'),1,array['knowledge.approve'])$$,'42501',null,'Agency cannot delegate to itself');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.set_agency_capabilities((select id from fixture where key='brand'),(select id from fixture where key='grant'),1,array['knowledge.write']);
select throws_ok($$select public.set_agency_capabilities((select id from fixture where key='brand'),(select id from fixture where key='grant'),1,array['knowledge.approve'])$$,'40001',null,'Stale permission edit fails');
select throws_ok($$select public.set_agency_capabilities((select id from fixture where key='brand'),(select id from fixture where key='grant'),2,array['workspace.manage'])$$,'23514',null,'Ownership cannot be delegated through workflow grant');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
insert into fixture values('fact',public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Test assertion','Test source','','Agency',current_date+30));
select throws_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),1,'approved')$$,'42501',null,'Editor cannot approve');
select throws_ok($$select public.create_client_report((select id from fixture where key='brand'),gen_random_uuid(),'Report',current_date,current_date,'')$$,'42501',null,'Editor cannot create reports');
insert into fixture values('staffinvite',public.invite_agency_staff((select id from fixture where key='agency'),'staff@example.invalid'));
select is(public.invite_agency_staff((select id from fixture where key='agency'),'staff@example.invalid'),(select id from fixture where key='staffinvite'),'Staff invitation retry coalesces');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$select public.accept_agency_staff((select id from fixture where key='staffinvite'))$$,'42501',null,'Wrong recipient cannot accept staff membership');
select public.set_agency_capabilities((select id from fixture where key='brand'),(select id from fixture where key='grant'),2,array['knowledge.approve','reports.create','opportunities.manage']);
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select lives_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),1,'approved')$$,'Explicit approver can approve current version');
select throws_ok($$select public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Other assertion','Source','','Agency',current_date+30)$$,'42501',null,'Approval does not imply editing');
select lives_ok($$select public.create_client_report((select id from fixture where key='brand'),gen_random_uuid(),'Report',current_date,current_date,'')$$,'Explicit report creator can snapshot');
select is((select count(*)::int from public.list_opportunity_assignees((select id from fixture where key='brand'))),2,'Assignment exposes current owner and agency member only');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_workspaces),0,'Staff invitation alone grants no client access');
select public.accept_agency_staff((select id from fixture where key='staffinvite'));
select is((select count(*)::int from public.brand_workspaces),1,'Accepted staff inherits agency client access');
select ok(public.current_brand_capability((select id from fixture where key='brand'),'reports.create'),'Staff receives explicit workflow grant');
select throws_ok($$select public.invite_agency_staff((select id from fixture where key='agency'),'other@example.invalid')$$,'42501',null,'Staff cannot administer agency');
select throws_ok($$select * from public.list_agency_staff((select id from fixture where key='agency'))$$,'42501',null,'Staff cannot list administrative roster');
select throws_ok($$select public.accept_agency_staff((select id from fixture where key='staffinvite'))$$,'22023',null,'Accepted invitation cannot replay');
insert into fixture values('source',public.register_brand_source((select id from fixture where key='brand'),'shopify','Staff shop','staff-test.myshopify.com'));
reset role;
update public.brand_sources set state='authorized',version=2 where id=(select id from fixture where key='source');
insert into private.connector_credentials(source_id,brand_id,encrypted_value,key_version,expires_at) values((select id from fixture where key='source'),(select id from fixture where key='brand'),'test-only','test',now()+interval '1 hour');
set local role authenticated;
insert into fixture values('run',public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid()));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.list_agency_staff((select id from fixture where key='agency'))),2,'Admin can review own roster');
select throws_ok($$select public.revoke_agency_staff((select id from fixture where key='agency'),'22222222-2222-4222-8222-222222222222')$$,'22023',null,'Cannot revoke agency creator');
select public.revoke_agency_staff((select id from fixture where key='agency'),'33333333-3333-4333-8333-333333333333');
reset role;
select ok(not private.run_authorized((select id from fixture where key='run')),'Staff revocation blocks queued job authority');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_workspaces),0,'Staff revocation removes actual RLS access');
select throws_ok($$select public.create_client_report((select id from fixture where key='brand'),gen_random_uuid(),'Report',current_date,current_date,'')$$,'42501',null,'Revoked staff cannot create reports');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.revoke_agency_access((select id from fixture where key='brand'),(select id from fixture where key='grant'));
insert into fixture values('reinvite',public.create_brand_invitation((select id from fixture where key='brand'),'agency@example.invalid','analyst',gen_random_uuid()));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select public.accept_brand_invitation((select id from fixture where key='reinvite'),(select id from fixture where key='agency'));
select ok(not public.current_brand_capability((select id from fixture where key='brand'),'knowledge.approve'),'Re-invitation cannot resurrect previous delegated approval');
select ok(not public.current_brand_capability((select id from fixture where key='brand'),'integrations.connect'),'New analyst invitation cannot resurrect operator access');
reset role;
select throws_ok($$delete from audit.agency_events$$,'42501',null,'Agency audit ledger is immutable');
select * from finish();
rollback;
